//! Perl: `Azul.pm` (generated by `doc/src/codegen/v2/lang_perl`,
//! FFI::Platypus, `use Azul;`).
//!
//! Spellings: every C function is attached into `Azul::FFI` under its C
//! name (`Azul::FFI::AzCssProperty_textColor(..)`, variant constructors
//! `Azul::FFI::AzLayoutWidth_px(..)`), C-like enum members are constant subs
//! (`Azul::AzLayoutDisplay::Flex()`), structs are `FFI::Platypus::Record`s
//! (`Azul::AzColorU->new(r => 255, ..)`) whose nested record fields hold the
//! nested value's bytes (`inner => ${ .. }`). Strings go through the
//! `css_str` helper (`AzString_fromUtf8` over the UTF-8 bytes).
//!
//! Limitations (like Python): a tagged union is a fake-layout record
//! (`sint32 tag` + a byte blob), so a `CssPropertyValue<T>` alias / a
//! `CssProperty` without a constructor cannot be built by hand, and a Vec
//! of 2+ items (whose stride would be that fake size) is not built - a
//! style is returned as a Perl array ref of its properties.

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use crate::codegen::{
    doc::{render, Doc},
    ir::{snake_to_lower_camel, EnumShape, Expr, Item, Module, Prim},
    lang::{
        escape_quoted, item_comments, item_doc, module_any, native_list, variant_ctor_method,
        ExprSyntax,
    },
    CodegenBackend, GeneratedFile,
};

/// The Perl printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct Perl;

/// Why the Perl printer does not export a DOM: every `Dom` crosses the FFI
/// by value, and its `NodeData` holds the `NodeType` union.
const DOM_REASON: &str = "the Perl binding lays every tagged union out as a fake record (`sint32` \
                          tag + `uint8[256]` payload, not its C layout), so a Dom - whose NodeData \
                          holds the NodeType union - has the wrong size when it crosses the FFI \
                          by value";

/// `\x{e9}`.
fn unicode_perl(cp: u32) -> String {
    format!("\\x{{{cp:x}}}")
}

impl ExprSyntax for Perl {
    fn int(&self, value: i128, _ty: Prim) -> String {
        value.to_string()
    }

    fn float(&self, text: &str, _ty: Prim) -> String {
        match text {
            "nan" => "9**9**9/9**9**9".to_string(),
            "inf" => "9**9**9".to_string(),
            "-inf" => "-9**9**9".to_string(),
            _ => text.to_string(),
        }
    }

    fn boolean(&self, b: bool) -> String {
        String::from(if b { "1" } else { "0" })
    }

    fn string(&self, s: &str) -> Doc {
        Doc::text(format!(
            "css_str(\"{}\")",
            escape_quoted(s, &['$', '@'], &unicode_perl)
        ))
    }

    fn call(&self, class: &str, method: &str, args: Vec<Doc>, broken: bool) -> Doc {
        Doc::call(
            format!("Azul::FFI::Az{class}_{}", snake_to_lower_camel(method)),
            args,
            broken,
        )
    }

    fn variant(&self, ty: &str, shape: EnumShape, variant: &str, args: Vec<Doc>, broken: bool) -> Doc {
        match shape {
            EnumShape::CLike => Doc::text(format!("Azul::Az{ty}::{variant}()")),
            EnumShape::Tagged => Doc::call(
                format!("Azul::FFI::Az{ty}_{}", variant_ctor_method(variant)),
                args,
                broken,
            ),
            // unreachable: `limitation` rejects hand-built unions
            EnumShape::TaggedShadowed | EnumShape::Generic { .. } => {
                Doc::text(format!("die(\"cannot build {ty}::{variant}\")"))
            }
        }
    }

    fn strukt(&self, ty: &str, fields: Vec<(String, Doc)>, broken: bool) -> Doc {
        let fields = fields
            .into_iter()
            .map(|(k, v)| Doc::cat(vec![Doc::text(format!("{k} => ")), v]))
            .collect();
        Doc::call(format!("Azul::Az{ty}->new"), fields, broken)
    }

    fn vec(&self, ty: &str, _elem: &str, items: Vec<Doc>, broken: bool) -> Doc {
        match items.len() {
            0 => Doc::text(format!("Azul::FFI::Az{ty}_create()")),
            // 2+ items are rejected by `limitation`
            _ => Doc::call(format!("Azul::FFI::Az{ty}_fromItem"), items, broken),
        }
    }

    fn unsupported(&self, what: &str) -> Doc {
        Doc::text(format!(
            "die(\"not expressible: {}\")",
            escape_quoted(what, &['$', '@'], &unicode_perl)
        ))
    }

    fn limitation(&self, e: &Expr) -> Option<String> {
        match e {
            Expr::Vec { ty, items, .. } if items.len() >= 2 => Some(format!(
                "the Perl bindings cannot build a {ty} of 2+ items (only create() / fromItem())"
            )),
            Expr::Variant {
                ty,
                shape: EnumShape::Generic { .. } | EnumShape::TaggedShadowed,
                ..
            } => Some(format!(
                "`{ty}` is a fake-layout record in the Perl bindings (tag + byte blob)"
            )),
            _ => None,
        }
    }

    fn dom_limitation(&self) -> Option<&'static str> {
        Some(DOM_REASON)
    }

    fn field_value(&self, field: &Expr, value: Doc) -> Doc {
        match field {
            Expr::Variant {
                shape: EnumShape::CLike,
                ..
            }
            | Expr::Int { .. }
            | Expr::Float { .. }
            | Expr::Bool(_) => value,
            // a nested record field holds the nested value's bytes
            _ => Doc::cat(vec![Doc::text("${ "), value, Doc::text(" }")]),
        }
    }
}

const CSS_STR: &str = "sub css_str {
    my ($s) = @_;
    utf8::encode($s);
    my ($ptr, $len) = FFI::Platypus::Buffer::scalar_to_buffer($s);
    return Azul::FFI::AzString_fromUtf8($ptr, $len);
}
";

fn item_fn(item: &Item) -> (bool, String) {
    let mut out = String::new();
    for line in &item_comments(&Perl, item) {
        out.push_str(&format!("# {line}\n"));
    }
    let name = item.name.snake();
    let body = native_list(&Perl, &item.value, "[", "]")
        .map(Ok)
        .unwrap_or_else(|| item_doc(&Perl, item));
    match body {
        Ok(doc) => {
            out.push_str(&format!(
                "sub {name} {{\n    return {};\n}}\n",
                render(&doc, "    ", 1)
            ));
            (true, out)
        }
        Err(reason) => {
            out.push_str(&format!(
                "# {name}: not expressible with the Perl bindings: {reason}\n"
            ));
            (false, out)
        }
    }
}

impl CodegenBackend for Perl {
    fn lang(&self) -> &'static str {
        "perl"
    }

    fn aliases(&self) -> &'static [&'static str] {
        &["pl"]
    }

    fn display_name(&self) -> &'static str {
        "Perl"
    }

    fn extension(&self) -> &'static str {
        "pl"
    }

    fn emit_module(&self, m: &Module) -> String {
        let mut out = String::from(
            "# Generated by azul-css codegen (Perl). Do not edit by hand.\npackage \
             AzulStyles;\nuse strict;\nuse warnings;\nuse Azul;\n",
        );
        if module_any(m, &|e| matches!(e, Expr::Str(_))) {
            out.push_str("use FFI::Platypus::Buffer ();\n\n");
            out.push_str(CSS_STR);
        }
        for item in &m.items {
            out.push('\n');
            out.push_str(&item_fn(item).1);
        }
        out.push_str("\n1;\n");
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        let mut main = String::from(
            "# Copy target/codegen/Azul.pm and libazul here, then:\n#   cpanm --installdeps . && \
             perl main.pl\nuse strict;\nuse warnings;\nuse lib '.';\nuse AzulStyles;\n\n",
        );
        for item in m.items.iter().filter(|i| item_fn(i).0) {
            let name = item.name.snake();
            main.push_str(&format!(
                "my ${name} = AzulStyles::{name}();\nprint \"{name}: \", scalar(@${name}), \" \
                 properties\\n\";\n"
            ));
        }
        vec![
            GeneratedFile {
                path: "cpanfile".to_string(),
                contents: "requires 'FFI::Platypus', '2.00';\nrequires 'FFI::CheckLib';\n"
                    .to_string(),
            },
            GeneratedFile {
                path: "AzulStyles.pm".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "main.pl".to_string(),
                contents: main,
            },
        ]
    }
}
